type hookedRenderer struct {
	linkifyProtocol []byte
	html.Config
}

func (r *hookedRenderer) SetOption(name renderer.OptionName, value any) {
	r.Config.SetOption(name, value)
}

// RegisterFuncs implements NodeRenderer.RegisterFuncs.
func (r *hookedRenderer) RegisterFuncs(reg renderer.NodeRendererFuncRegisterer) {
	reg.Register(ast.KindLink, r.renderLink)
	reg.Register(ast.KindAutoLink, r.renderAutoLink)
	reg.Register(ast.KindImage, r.renderImage)
	reg.Register(ast.KindHeading, r.renderHeading)
}

func (r *hookedRenderer) renderImage(w util.BufWriter, source []byte, node ast.Node, entering bool) (ast.WalkStatus, error) {
	n := node.(*ast.Image)
	var lr hooks.LinkRenderer

	ctx, ok := w.(*render.Context)
	if ok {
		h := ctx.RenderContext().GetRenderer(hooks.ImageRendererType, nil)
		ok = h != nil
		if ok {
			lr = h.(hooks.LinkRenderer)
		}
	}

	if !ok {
		if !entering {
			return ast.WalkContinue, nil
		}

		_, _ = w.WriteString("<img src=\"")
		destination := n.Destination
		if r.Unsafe || !html.IsDangerousURL(destination) {
			escapedDestination := util.EscapeHTML(util.URLEscape(destination, true))
			_, _ = w.Write(escapedDestination)
		}
		_, _ = w.WriteString(`" alt="`)
		altText := nodeToHTMLText(n, source)
		_, _ = w.Write(altText)
		_ = w.WriteByte('"')

		title := n.Title
		if title != nil {
			_, _ = w.WriteString(` title="`)
			r.Writer.Write(w, title)
			_ = w.WriteByte('"')
		}

		rawAttrs := n.Attributes()
		if rawAttrs != nil {
			filteredAttrs := r.filterInternalAttributes(rawAttrs)
			for _, attr := range filteredAttrs {
				attrName := strings.ToLower(string(attr.Name))
				if strings.HasPrefix(attrName, "on") {
					continue
				}
				_, _ = w.WriteString(" ")
				_, _ = w.Write(attr.Name)
				_, _ = w.WriteString(`="`)
				switch value := attr.Value.(type) {
				case []byte:
					_, _ = w.Write(util.EscapeHTML(value))
				default:
					_, _ = w.WriteString(cast.ToString(value))
				}
				_ = w.WriteByte('"')
			}
		}

		if r.XHTML {
			_, _ = w.WriteString(" />")
		} else {
			_, _ = w.WriteString(">")
		}
		return ast.WalkSkipChildren, nil
	}

	if entering {
		// Store the current pos so we can capture the rendered text.
		currentLen := ctx.Buffer.Len()
		ctx.PushPos(currentLen)
		return ast.WalkContinue, nil
	}

	startPos := ctx.PopPos()
	captured := ctx.Buffer.Bytes()[startPos:]
	ctx.Buffer.Truncate(startPos)

	isBlock := false
	if blockVal, found := n.AttributeString(images.AttrIsBlock); found {
		isBlock = blockVal.(bool)
	}

	ordinal := 0
	if ordinalVal, found := n.AttributeString(images.AttrOrdinal); found {
		ordinal = ordinalVal.(int)
	}

	// We use the attributes to signal from the parser whether the image is in
	// a block context or not.
	// We may find a better way to do that, but for now, we'll need to remove any
	// internal attributes before rendering.
	filteredAttrs := r.filterInternalAttributes(n.Attributes())
	safeAttrs := make([]ast.Attribute, 0, len(filteredAttrs))
	for _, attr := range filteredAttrs {
		attrName := strings.ToLower(string(attr.Name))
		if strings.HasPrefix(attrName, "on") {
			continue
		}
		safeAttrs = append(safeAttrs, attr)
	}

	holder := attributes.New(safeAttrs, attributes.AttributesOwnerGeneral)
	page := ctx.DocumentContext().Document
	destination := string(n.Destination)
	title := string(n.Title)
	plainText := string(n.Text(source))
	renderedText := hstring.RenderedString(captured)
	renderCtx := ctx.RenderContext()

	err := lr.RenderLink(
		renderCtx.Ctx,
		w,
		imageLinkContext{
			linkContext: linkContext{
				page:             page,
				destination:      destination,
				title:            title,
				text:             renderedText,
				plainText:        plainText,
				AttributesHolder: holder,
			},
			ordinal: ordinal,
			isBlock: isBlock,
		},
	)

	return ast.WalkContinue, err
}

func (r *hookedRenderer) filterInternalAttributes(attrs []ast.Attribute) []ast.Attribute {
	n := 0
	for _, x := range attrs {
		if !bytes.HasPrefix(x.Name, []byte(internalAttrPrefix)) {
			attrs[n] = x
			n++
		}
	}
	return attrs[:n]
}

// Fall back to the default Goldmark render funcs. Method below borrowed from:
// https://github.com/yuin/goldmark/blob/b611cd333a492416b56aa8d94b04a67bf0096ab2/renderer/html/html.go#L404
func (r *hookedRenderer) renderImageDefault(w util.BufWriter, source []byte, node ast.Node, entering bool) (ast.WalkStatus, error) {
	if !entering {
		return ast.WalkContinue, nil
	}
	n := node.(*ast.Image)
	_, _ = w.WriteString("<img src=\"")
	if r.Unsafe || !html.IsDangerousURL(n.Destination) {
		_, _ = w.Write(util.EscapeHTML(util.URLEscape(n.Destination, true)))
	}
	_, _ = w.WriteString(`" alt="`)
	_, _ = w.Write(nodeToHTMLText(n, source))
	_ = w.WriteByte('"')
	if n.Title != nil {
		_, _ = w.WriteString(` title="`)
		r.Writer.Write(w, n.Title)
		_ = w.WriteByte('"')
	}
	if n.Attributes() != nil {
		attrs := r.filterInternalAttributes(n.Attributes())
		attributes.RenderASTAttributes(w, attrs...)
	}
	if r.XHTML {
		_, _ = w.WriteString(" />")
	} else {
		_, _ = w.WriteString(">")
	}
	return ast.WalkSkipChildren, nil
}

